create extension if not exists pgcrypto; create schema if not exists private;
create table public.roles(id uuid primary key default gen_random_uuid(),code text not null unique check(code in('student','parent','teacher','curator','admin')),name text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.roles(code,name) values('student','Ученик'),('parent','Родитель'),('teacher','Преподаватель'),('curator','Куратор'),('admin','Администратор') on conflict do nothing;
create table public.profiles(id uuid primary key references auth.users(id) on delete restrict,first_name text not null default'',last_name text not null default'',phone text,city text,timezone text not null default'Europe/Moscow',deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid references public.profiles(id) on delete cascade,role_id uuid references public.roles(id) on delete restrict,granted_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(user_id,role_id));
create table public.student_profiles(user_id uuid primary key references public.profiles(id) on delete restrict,birth_date date,grade smallint check(grade between 5 and 11),school text,onboarding_status text not null default'not_started' check(onboarding_status in('not_started','in_progress','completed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.parent_profiles(user_id uuid primary key references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.teacher_profiles(user_id uuid primary key references public.profiles(id) on delete restrict,bio text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.curator_profiles(user_id uuid primary key references public.profiles(id) on delete restrict,bio text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.parent_student_links(id uuid primary key default gen_random_uuid(),parent_id uuid references public.parent_profiles(user_id) on delete restrict,student_id uuid references public.student_profiles(user_id) on delete restrict,relation text not null,status text not null default'pending' check(status in('pending','confirmed','revoked','rejected')),confirmed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(parent_id,student_id));
create table public.invitations(id uuid primary key default gen_random_uuid(),inviter_id uuid references public.profiles(id) on delete restrict,intended_role text not null,email text,phone text,token_hash text not null unique,expires_at timestamptz not null,accepted_at timestamptz,attempts smallint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(email is not null or phone is not null));
create table public.exam_types(id uuid primary key default gen_random_uuid(),code text not null unique check(code in('ege','oge')),name text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subjects(id uuid primary key default gen_random_uuid(),exam_type_id uuid references public.exam_types(id) on delete restrict,code text not null,name text not null,active boolean not null default true,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(exam_type_id,code));
create table public.programs(id uuid primary key default gen_random_uuid(),subject_id uuid references public.subjects(id) on delete restrict,title text not null,status text not null default'draft' check(status in('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.modules(id uuid primary key default gen_random_uuid(),program_id uuid references public.programs(id) on delete restrict,title text not null,position int not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(program_id,position));
create table public.topics(id uuid primary key default gen_random_uuid(),module_id uuid references public.modules(id) on delete restrict,title text not null,position int not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(module_id,position));
create table public.student_subjects(id uuid primary key default gen_random_uuid(),student_id uuid references public.student_profiles(user_id) on delete restrict,subject_id uuid references public.subjects(id) on delete restrict,current_grade smallint,self_reported_last_mock_score smallint,confidence smallint,target_score smallint not null check(target_score between 0 and 100),status text not null default'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(student_id,subject_id));
create table public.admission_goals(id uuid primary key default gen_random_uuid(),student_id uuid references public.student_profiles(user_id) on delete restrict,institution_type text not null,institution_name text not null,direction_name text,desired_score smallint,priority smallint,funding_type text,status text not null default'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.plans(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,base_price_minor int not null,currency char(3) not null default'RUB',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.plan_features(id uuid primary key default gen_random_uuid(),plan_id uuid references public.plans(id) on delete cascade,feature_code text not null,limit_value int,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(plan_id,feature_code));
create table public.subscriptions(id uuid primary key default gen_random_uuid(),student_id uuid references public.student_profiles(user_id) on delete restrict,plan_id uuid references public.plans(id) on delete restrict,status text not null check(status in('draft','pending','active','paused','cancelled','expired')),starts_at timestamptz,ends_at timestamptz,price_minor int not null,source text not null default'manual',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscription_subjects(subscription_id uuid references public.subscriptions(id) on delete cascade,subject_id uuid references public.subjects(id) on delete restrict,status text not null default'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(subscription_id,subject_id));
create table public.payments(id uuid primary key default gen_random_uuid(),subscription_id uuid references public.subscriptions(id) on delete restrict,payer_id uuid references public.profiles(id),provider text not null default'manual',idempotency_key text not null unique,amount_minor int not null,status text not null,paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.groups(id uuid primary key default gen_random_uuid(),program_id uuid references public.programs(id) on delete restrict,name text not null,timezone text not null default'Europe/Moscow',status text not null default'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.group_students(group_id uuid references public.groups(id),student_id uuid references public.student_profiles(user_id),joined_at timestamptz not null default now(),left_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(group_id,student_id));
create table public.group_teachers(group_id uuid references public.groups(id),teacher_id uuid references public.teacher_profiles(user_id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(group_id,teacher_id));
create table public.curator_students(curator_id uuid references public.curator_profiles(user_id),student_id uuid references public.student_profiles(user_id),active_to timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(curator_id,student_id));
create table public.lessons(id uuid primary key default gen_random_uuid(),group_id uuid references public.groups(id),subject_id uuid references public.subjects(id),teacher_id uuid references public.teacher_profiles(user_id),title text not null,description text,status text not null default'scheduled',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.schedule_events(id uuid primary key default gen_random_uuid(),lesson_id uuid references public.lessons(id) on delete cascade,group_id uuid references public.groups(id),subject_id uuid references public.subjects(id),event_type text not null,title text not null,starts_at timestamptz not null,ends_at timestamptz not null,timezone text not null,status text not null default'scheduled',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.meeting_links(lesson_id uuid primary key references public.lessons(id) on delete cascade,provider text not null,join_url text not null,host_secret_ciphertext text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.lesson_recordings(id uuid primary key default gen_random_uuid(),lesson_id uuid references public.lessons(id) on delete cascade,storage_path text,external_url text,status text not null default'processing',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.lesson_attendance(lesson_id uuid references public.lessons(id),student_id uuid references public.student_profiles(user_id),status text not null,marked_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(lesson_id,student_id));
create table public.materials(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles(id),title text not null,material_type text not null,storage_path text,external_url text,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.assignments(id uuid primary key default gen_random_uuid(),group_id uuid references public.groups(id),subject_id uuid references public.subjects(id),teacher_id uuid references public.teacher_profiles(user_id),title text not null,due_at timestamptz not null,max_score numeric not null,status text not null default'published',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.assignment_submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid references public.assignments(id),student_id uuid references public.student_profiles(user_id),status text not null default'not_started',score numeric,submitted_at timestamptz,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assignment_id,student_id));
create table public.mock_exams(id uuid primary key default gen_random_uuid(),subject_id uuid references public.subjects(id),title text not null,duration_minutes int not null,status text not null default'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.mock_exam_assignments(id uuid primary key default gen_random_uuid(),mock_exam_id uuid references public.mock_exams(id),student_id uuid references public.student_profiles(user_id),starts_at timestamptz not null,available_until timestamptz not null,status text not null default'scheduled',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.student_score_forecasts(id uuid primary key default gen_random_uuid(),student_id uuid references public.student_profiles(user_id),subject_id uuid references public.subjects(id),forecast_score smallint not null,target_score smallint not null,formula_version text not null,inputs jsonb not null,explanation text not null,computed_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id),type text not null,title text not null,body text not null,channel text not null default'in_app',read_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id text,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());

create function private.has_role(c text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=auth.uid() and r.code=c)$$;
create function private.parent_of(s uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.parent_student_links where parent_id=auth.uid() and student_id=s and status='confirmed')$$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$declare r text;begin r:=case when new.raw_user_meta_data->>'intended_role' in('student','parent') then new.raw_user_meta_data->>'intended_role' else 'student' end;insert into public.profiles(id,first_name)values(new.id,coalesce(new.raw_user_meta_data->>'first_name',''));insert into public.user_roles select new.id,roles.id,null,now(),now() from public.roles where code=r;if r='student' then insert into public.student_profiles(user_id)values(new.id);else insert into public.parent_profiles(user_id)values(new.id);end if;return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

do $$declare t text;begin foreach t in array array['roles','profiles','user_roles','student_profiles','parent_profiles','teacher_profiles','curator_profiles','parent_student_links','invitations','exam_types','subjects','programs','modules','topics','student_subjects','admission_goals','plans','plan_features','subscriptions','subscription_subjects','payments','groups','group_students','group_teachers','curator_students','lessons','schedule_events','meeting_links','lesson_recordings','lesson_attendance','materials','assignments','assignment_submissions','mock_exams','mock_exam_assignments','student_score_forecasts','notifications','audit_logs'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy roles_read on public.roles for select using(auth.uid() is not null);
create policy profiles_scope on public.profiles for select using(id=auth.uid() or private.has_role('admin') or private.parent_of(id)); create policy profiles_own_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy user_roles_read on public.user_roles for select using(user_id=auth.uid() or private.has_role('admin'));
create policy student_profiles_scope on public.student_profiles for select using(user_id=auth.uid() or private.parent_of(user_id) or private.has_role('admin'));create policy student_profiles_own_update on public.student_profiles for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy parent_profiles_own on public.parent_profiles for select using(user_id=auth.uid() or private.has_role('admin'));create policy teachers_read on public.teacher_profiles for select using(auth.uid() is not null);create policy curators_read on public.curator_profiles for select using(auth.uid() is not null);
create policy links_scope on public.parent_student_links for select using(parent_id=auth.uid() or student_id=auth.uid() or private.has_role('admin'));
create policy subjects_public on public.subjects for select using(active and deleted_at is null or private.has_role('admin'));create policy exams_public on public.exam_types for select using(active or private.has_role('admin'));create policy plans_public on public.plans for select using(active or private.has_role('admin'));create policy features_public on public.plan_features for select using(true);
create policy student_subjects_scope on public.student_subjects for select using(student_id=auth.uid() or private.parent_of(student_id) or private.has_role('admin'));create policy student_subjects_own on public.student_subjects for all using(student_id=auth.uid()) with check(student_id=auth.uid());
create policy subscriptions_scope on public.subscriptions for select using(student_id=auth.uid() or private.parent_of(student_id) or private.has_role('admin'));create policy payments_scope on public.payments for select using(payer_id=auth.uid() or private.has_role('admin'));
create policy groups_members on public.groups for select using(private.has_role('admin') or exists(select 1 from public.group_students where group_id=id and student_id=auth.uid()) or exists(select 1 from public.group_teachers where group_id=id and teacher_id=auth.uid()));
create policy group_students_scope on public.group_students for select using(student_id=auth.uid() or private.parent_of(student_id) or private.has_role('teacher') or private.has_role('curator') or private.has_role('admin'));create policy group_teachers_scope on public.group_teachers for select using(teacher_id=auth.uid() or private.has_role('admin'));
create policy lessons_scope on public.lessons for select using(private.has_role('admin') or teacher_id=auth.uid() or exists(select 1 from public.group_students where group_id=lessons.group_id and student_id=auth.uid()));
create policy schedule_scope on public.schedule_events for select using(private.has_role('admin') or exists(select 1 from public.group_students where group_id=schedule_events.group_id and student_id=auth.uid()) or exists(select 1 from public.group_teachers where group_id=schedule_events.group_id and teacher_id=auth.uid()));
create policy attendance_scope on public.lesson_attendance for select using(student_id=auth.uid() or private.parent_of(student_id) or private.has_role('teacher') or private.has_role('curator') or private.has_role('admin'));create policy attendance_staff_write on public.lesson_attendance for all using(private.has_role('teacher') or private.has_role('admin')) with check(private.has_role('teacher') or private.has_role('admin'));
create policy assignments_scope on public.assignments for select using(private.has_role('admin') or teacher_id=auth.uid() or exists(select 1 from public.group_students where group_id=assignments.group_id and student_id=auth.uid()));create policy submissions_scope on public.assignment_submissions for select using(student_id=auth.uid() or private.parent_of(student_id) or private.has_role('teacher') or private.has_role('curator') or private.has_role('admin'));create policy submissions_own_open on public.assignment_submissions for insert with check(student_id=auth.uid());
create policy mocks_read on public.mock_exams for select using(auth.uid() is not null);create policy mock_assignments_scope on public.mock_exam_assignments for select using(student_id=auth.uid() or private.parent_of(student_id) or private.has_role('teacher') or private.has_role('curator') or private.has_role('admin'));create policy forecasts_scope on public.student_score_forecasts for select using(student_id=auth.uid() or private.parent_of(student_id) or private.has_role('curator') or private.has_role('admin'));create policy notifications_own on public.notifications for select using(user_id=auth.uid() or private.has_role('admin'));create policy audit_admin on public.audit_logs for select using(private.has_role('admin'));

insert into storage.buckets(id,name,public) values('lesson-materials','lesson-materials',false),('lesson-recordings','lesson-recordings',false),('student-submissions','student-submissions',false) on conflict(id) do update set public=false;
